package com.bank.directory;

import java.util.*;
import java.util.logging.*;

public class DirectoryDemo {
    private static final Logger log = Logger.getLogger("Directory");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = new ArrayList<>(Arrays.asList(
            new Employee(1L, "Rajesh", "Mumbai"),
            new Employee(2L, "Priya", null),
            new Employee(3L, "Amit", "Bengaluru"),
            new Employee(4L, "Sneha", null),
            new Employee(5L, "Vikram", "Delhi")
        ));
        DirectoryService service = new DirectoryService();
        List<Employee> sorted = service.sortByCityNullsLast(staff);
        log.info("Directory (city A-Z, missing city last):");
        sorted.forEach(e -> log.info(() ->
            String.format("  %-9s | %s", e.getName(), e.getCity() == null ? "<none>" : e.getCity())));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final Long id;
    private final String name;
    private final String city; // nullable
        Employee(Long id, String name, String city) { this.id = id;
        this.name = name
        this.city = city; }
    String getName() { return name; }
    String getCity() { return city; }
}

// ─── Would be in service/DirectoryService.java ───
class DirectoryService {
    // nullsLast makes the city comparison null-safe: missing city sorts to the end.
    List<Employee> sortByCityNullsLast(List<Employee> employees) {
        return employees.stream()
            .sorted(Comparator.comparing(Employee::getCity,
                        Comparator.nullsLast(Comparator.naturalOrder()))
                    .thenComparing(Employee::getName))
            .toList();
    }
}
